export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "22:35。受控事故檔案室。M 區走廊盡頭一間沒有窗戶的房間。比臨時指揮室更窄。更安靜。牆邊有一排鐵櫃。鐵櫃上貼著封條。封條上的日期——十年前。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原站在桌的一端。她沒有坐下。法律顧問在她右後方。手裡拿著一份書面目錄。每翻一頁，都在欄位裡填時間、責任人與閱覽者。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家坐在桌的另一端。他的終端接著警方保全的資料碟。不接設施內部網路。不接凪原帶來的設備。只看獨立材料。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部站在門邊。雙臂交叉。三浦在走廊另一端處理令狀後續。外部醫師已經回 M-00 醫療區值班。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在摺疊椅上。第三杯水。杯壁上的水珠已經乾了一半。她看著桌上那些鐵櫃。十年前的封條。十年前的日期。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯十年前。函館。夜潮。⋯⋯不是潮災。不是海嘯。是什麼。⋯⋯她要打開那些櫃子了。她只開放跟媽媽直接相關的第一層。技術原始檔由指定專家和警方同步核對。⋯⋯我只看得到跟媽媽有關的部分。其他封緘。⋯⋯好。先看跟媽媽有關的。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "函館夜潮第一層事故資料。來源——函館近郊舊觀測站、岸站、兩艘船舶、遠距觀測點、醫院、軍事態勢融合紀錄、暴露者封存材料。我只開放與朝倉紗英直接相關的節錄。技術原始檔由指定專家獨立核對。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.CabinetLegalAdvisor, character: "內閣法律顧問", dialogue: "書面目錄第一項。函館第一層事故資料。來源標示如上。閱覽者——朝倉澪、日下部悟、指定專家。第三方及國際個資封緘。不銷毀。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原走到鐵櫃前。她沒有戴手套。她抽出一個文件夾。藍色封面。封面上只有一行字。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "函館夜潮——暴露者意象紀錄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把文件夾放在桌上。翻開第一頁。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不是照片。是手寫的。鉛筆。紙質泛黃。字跡不同——至少六個人寫的。有些像護士的記錄。有些像研究員的筆記。有些只是歪歪扭扭的幾個字。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一頁。日期——十年前。事故當晚。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "內容——", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "「黑暗。平面。不反光。像瀝青。不是水。」", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "「月光在錯的地方。左邊。不對。」", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "「七次。亮的。很快。」", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "「海聲。但不是海。壓迫感。耳朵痛。」", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "六個人。六種寫法。沒有人畫出完整的圖。每個人都只記得碎片。黑暗平面。錯位月光。七次亮脈衝。海聲或壓迫感。零散。像拼圖被拆開後各自帶走一塊。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯黑暗平面。錯位月光。七次亮脈衝。⋯⋯這些。這些是黑色海的零件。⋯⋯悠真畫過。水瀨葵畫過。佐伯蓮畫過。藤川美空說過。⋯⋯可是這裡——十年前——沒有人畫出完整的海。沒有倒月。沒有七條線。沒有遠方光。只有碎片。只有零件。⋯⋯完整的黑色海。是後來才出現的。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原翻到第二組。日期——事故後第一日。第二日。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "這一組不一樣。不是六個人的零散筆記。是一個人的。字跡穩。像研究員的記錄習慣。每頁右上角都寫了日期。每頁都有鉛筆素描。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一張。黑暗平面。但這一次——有形狀。有邊界。像一片真正的海面。不反光。但有一個方向。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二張。月亮。倒過來的。掛在畫面上方。不是錯位。是明確地倒著。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第三張。七條線。平行。從海面延伸到畫面上方。等距。像被尺量過。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第四張。遠方有光。很小。在海面的盡頭。不是太陽。不是燈塔。只是一個點。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日期——事故後第二日。簽名處——紗英。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯紗英。媽媽。⋯⋯是她。是她第一個畫出完整的黑色海。倒月。七條線。遠方光。⋯⋯其他人只記得碎片。她——把碎片拼成了整幅圖。⋯⋯事故後第二天。她還能寫日期。她還能簽名。她還能畫。⋯⋯後來呢。後來她就不能了。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原沒有看澪。她看著文件夾。她的聲音像在讀目錄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "事故當晚，各暴露者只留下零散共同元素。黑暗平面、錯位月光、七次亮脈衝、海聲或壓迫感。沒有人留下完整構圖。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "事故後第一至第二日，朝倉紗英首次留下完整黑色海、倒月、七線及遠方光的構圖。這是目前已知最早的完整版本。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到第三組。日期跨度更長。從事故後數週到數月。多個不同人的記錄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "這一組裡，完整構圖開始反覆出現。不同的人。不同的時間。但畫出來的東西——幾乎一樣。黑色海。倒月。七條線。遠方光。標準化。像從同一個模板印出來的。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "每份記錄的右上角都有一個標記。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "M-00 投入後。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "第三組材料。日期與前兩組不重疊。來源獨立。M-00 模型投入後，後續接收者的完整構圖逐步標準化。標準化版本與紗英第二日構圖高度一致。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "能證明什麼。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "能證明——三組材料有各自獨立的日期。事故當晚只有零散元素。紗英第 1–2 日首次出現完整構圖。M-00 投入後，完整構圖在後續接收者間標準化。時間順序成立。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不能證明什麼。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "不能證明——黑色海必然只是翻譯層。不能證明——所有影像都是客觀未來。不能證明——函館資料不存在研究暗示或選擇偏差。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部點了一下頭。他看向澪。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "三組日期。三個階段。碎片。完整。標準化。聽清楚了？", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "聽清楚了。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯碎片。完整。標準化。⋯⋯媽媽把碎片拼成了完整圖。然後 M-00 把媽媽的完整圖變成了模板。其他孩子看到的——不是訊號的原貌。是媽媽翻譯過的版本。⋯⋯悠真畫的海。水瀨葵畫的海。佐伯蓮畫的海。⋯⋯都先在媽媽腦中出現過。⋯⋯不。還不能下這個結論。指定專家說了——不能證明必然只是翻譯層。⋯⋯可是時間順序。碎片在先。完整在後。標準化在最後。⋯⋯如果不是翻譯層——為什麼事故當晚沒有人看見完整的海？", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原從文件夾裡抽出一張紙。不是圖。是文字。手寫。日期——事故後第七日。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的字跡。比第二日的更潦草。像在很疲倦的狀態下寫的。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "內容——", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "「港區。燈架倒。水漫到路面。三個人。玻璃。」", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "沒有更多。只有這幾個字。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "這是紗英在事故後第七日留下的片段。描述的是一場尚未發生的港區事故。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。像在選擇用詞。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "港區事故在紗英寫下這段文字後數日才發生。第三方時間紀錄早於事件。細節後來部分吻合。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "部分吻合。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "部分吻合。不是全部。燈架確實倒了。水確實漫到路面。人數——實際是兩人受傷，不是三人。玻璃——現場確實有碎玻璃，但來源是附近施工圍籬，不是港區設施。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "所以是巧合。提前資訊。還是選擇性記憶。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "三種解釋都無法排除。第三方時間紀錄支持文字早於事件。但樣本數為一。不能以此建立規律。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯媽媽在事故後第七天。寫下了還沒發生的事。⋯⋯部分吻合。不是全部。⋯⋯可是日期。日期是別人能查的。不是她自己說的。⋯⋯先記著。不能下結論。先記著。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "23:15。凪原合上暴露者意象紀錄。她從另一個鐵櫃裡抽出一個更厚的文件夾。灰色封面。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "封面——函館夜潮——感測資料與態勢融合紀錄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "這一組資料由指定專家獨立核對。我只提供與紗英直接相關的脈絡說明。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家把終端轉向自己那一側。他打開警方保全的資料碟。調出函館舊觀測站的原始紀錄摘要。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "函館近郊舊觀測站。已轉為天文／通訊監測用途。事件當晚——觀測站記錄到一段結構化脈衝。核心脈衝短。弱訊號持續數小時。這是目前已知最早的完整原始訊號紀錄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "岸站、兩艘船舶、遠距觀測點的紀錄在事件後由第三方校正。原始資料在各單位互相接觸前已封存。到達順序——不符合地面或海底轉播模式。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "什麼意思。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "如果是地面轉播，訊號應該沿固定路徑到達各站。到達時間應該符合地理距離。實際紀錄——不符合。各站幾乎同時收到。但不是完全同時。時間差不符合任何已知傳播模式。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著指定專家的終端。她看不懂原始數據。但她看得懂時間軸。幾個點。幾條線。時間差標在線上。數字不對。如果從函館發出，岸站應該最先收到。但岸站和船舶的時間差——只有零點幾秒。不夠光走那段距離。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯時間差不對。不是從地面傳的。不是從海底傳的。⋯⋯那從哪裡傳的。⋯⋯先聽。先不問。讓指定專家說完。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "23:40。凪原走到鐵櫃前。她抽出最後一個文件夾。深紅色封面。比其他都薄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "封面——函館夜潮——軍事態勢融合紀錄。節錄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "法律顧問翻了一頁目錄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.CabinetLegalAdvisor, character: "內閣法律顧問", dialogue: "書面目錄第二項。軍事態勢融合紀錄節錄。閱覽者——指定專家、日下部悟。家屬閱覽一般語言摘要。不閱覽完整技術數據。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家接過文件夾。他翻開。看了幾頁。眉頭收緊。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "流程是這樣的。沿岸與觀測感測器受到結構化脈衝污染。感測器記錄到異常反射和時間資料。這些資料依正常流程進入海空態勢融合系統。系統把矛盾反射與時間資料組合成——不存在的航跡。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "假航跡。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "假航跡。不是訊號直接在雷達上畫出飛機。是感測器被污染後，融合系統按照正常算法把矛盾數據拼成了看起來合理的航跡。系統不知道自己在拼假的。它只是在做它被設計來做的事。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻了一頁。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "同時——值勤人員受到認知異常影響。部分人員出現幻覺、方向感錯亂、判斷力下降。他們看到融合系統輸出的假航跡時，懷疑閾值比正常低。平時會質疑的數據，那晚沒有人質疑。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "所以系統輸出假航跡。人看到假航跡不懷疑。兩者互相證明。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "是。系統的假航跡讓人相信有威脅。人的確認讓系統的假航跡看起來被獨立驗證。兩者互相放大。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到最後一頁。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "日本與鄰近海域單位互相誤讀警戒反應。攔截機升空。外國船舶誤認被鎖定。命令在最後數分鐘撤銷。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "房間裡安靜了幾秒。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯最後數分鐘。差點。差點就——⋯⋯不是飛彈。不是戰爭。是感測器被污染。融合系統拼出假航跡。人不懷疑。兩者互相證明。⋯⋯同一段異常——同時改變了系統看到的東西和人看到的東西。兩者又互相證明對方是對的。⋯⋯這就是凪原害怕的。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看向凪原。凪原站在鐵櫃旁邊。她的手放在櫃面上。指尖沒有動。但她的肩膀——比之前高了半公分。像在吸氣。像在控制某種東西不讓它出來。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯她在怕。她的肩膀緊了。她在看那份深紅色文件夾。⋯⋯她十年前在現場。她看見了。她看見十七個人同時昏迷。她看見假航跡。她看見攔截機升空。她看見命令在最後幾分鐘撤銷。⋯⋯她怕的不是外星人。她怕的是——同一段東西同時改變機器和人。機器不知道自己在說謊。人不知道自己在配合。⋯⋯她怕了十年。然後她把恐懼變成了制度。把制度變成了拘束。把拘束變成了十年。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部看著指定專家。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "這些紀錄能證明什麼。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "能證明——感測污染進入融合系統是事實。假航跡是事實。值勤人員認知異常是事實。命令在最後數分鐘撤銷是事實。軍事近失是事實。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不能證明什麼。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "不能證明——下一次相同事件必然發生。不能證明——M-00 中止必然導致相同層級的軍事風險。不能證明——十年拘束是唯一有效的預防方式。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "正式紀錄。軍事近失——事實。十年拘束與軍事近失的因果——尚需驗證。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.CabinetLegalAdvisor, character: "內閣法律顧問", dialogue: "已記錄。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "00:00。受控事故檔案室。鐵櫃。封條。三組日期材料。軍事近失的節錄。紗英的手寫字。紗英的素描。十年前的黑暗平面。十年前的錯位月光。十年前的七次亮脈衝。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著桌上那個藍色文件夾。翻開的那一頁。紗英的簽名。事故後第二日。完整的黑色海。倒月。七條線。遠方光。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯媽媽。⋯⋯妳是第一個看見完整海的人。⋯⋯其他人都只看到碎片。妳把它拼起來了。⋯⋯然後他們把妳的拼圖拿走。做成模板。塞進機器。塞進其他孩子的腦裡。⋯⋯十年。⋯⋯妳畫的那片海。變成了悠真畫的那片海。變成了水瀨葵畫的那片海。變成了所有孩子夢裡的那片海。⋯⋯那不是訊號的海。⋯⋯那是妳的海。", background: Background.Chapter_20_Ch20_Act4_S0, portrait: Portrait.AsakuraMio_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "00:05。凪原把文件夾收回鐵櫃。封條重新貼上。法律顧問在目錄上簽了時間。", background: Background.Chapter_20_Ch20_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約五日六小時八分鐘。", background: Background.Chapter_20_Ch20_Act4_S0 },
];
